create table public.research_runs (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, status text not null, provider text, model text, started_at timestamptz, completed_at timestamptz, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.research_claims (id uuid primary key default gen_random_uuid(), research_run_id uuid not null references public.research_runs(id) on delete cascade, field_path text not null, claim text not null, confidence numeric(4,3) check(confidence between 0 and 1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.research_sources (id uuid primary key default gen_random_uuid(), research_claim_id uuid not null references public.research_claims(id) on delete cascade, title text not null, url text not null, publisher text, published_at timestamptz, retrieved_at timestamptz not null default now());
create table public.verification_results (id uuid primary key default gen_random_uuid(), research_claim_id uuid not null references public.research_claims(id) on delete cascade, status text not null, rationale text, verified_by text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.entity_field_provenance (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, field_path text not null, origin text not null, source_id uuid, version text not null default '1', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index field_provenance_entity_idx on public.entity_field_provenance(entity_type,entity_id);
create table public.import_sources (id uuid primary key default gen_random_uuid(), name text not null, source_type text not null, base_url text, configuration jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.imported_entities (id uuid primary key default gen_random_uuid(), import_source_id uuid not null references public.import_sources(id), external_id text not null, entity_type text not null, canonical_entity_id uuid, payload jsonb not null, imported_at timestamptz not null default now(), unique(import_source_id,external_id));
create table public.duplicate_candidates (id uuid primary key default gen_random_uuid(), left_entity_id uuid not null, right_entity_id uuid not null, entity_type text not null, confidence numeric(4,3) not null check(confidence between 0 and 1), status text not null default 'pending', reviewed_by uuid references public.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.entity_redirects (id uuid primary key default gen_random_uuid(), entity_type text not null, from_slug text not null, to_entity_id uuid not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(entity_type,from_slug));
create table public.moderation_flags (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, reason text not null, status text not null default 'open', reported_by uuid references public.users(id), reviewed_by uuid references public.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_type text not null, actor_id uuid, action text not null, entity_type text not null, entity_id uuid, before jsonb, after jsonb, request_id text, created_at timestamptz not null default now());

alter table public.users enable row level security;
alter table public.user_wallets enable row level security;
alter table public.organizations enable row level security;
alter table public.organization_members enable row level security;
create policy "public published problems" on public.problems for select using (status='published' and deleted_at is null);
create policy "public published ideas" on public.ideas for select using (status='published' and deleted_at is null);
alter table public.problems enable row level security;
alter table public.ideas enable row level security;
